#nullable enable // autogenerated

using MVZ2.Level.Inputing;
using MVZ2.UI;
using MVZ2Logic.Inputs;
using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace MVZ2.Blueprints
{
    public class BlueprintDisplayerMobile : BlueprintDisplayer
    {
        public override void UpdateItems(ChoosingBlueprintViewData[] viewDatas)
        {
            blueprintList.updateList(viewDatas.Length, (i, rect) =>
            {
                var blueprint = rect.GetComponent<Blueprint>();
                blueprint.UpdateView(viewDatas[i].blueprint);
                blueprint.SetDisabled(viewDatas[i].disabled);
                blueprint.SetSelected(viewDatas[i].selected);
                blueprint.SetRecharge(viewDatas[i].recharge);
            },
            rect =>
            {
                var page = rect.GetComponent<Blueprint>();
                page.OnPointerInteraction += OnPointerInteractionCallback;
                page.OnSelect += OnSelectCallback;
            },
            rect =>
            {
                var page = rect.GetComponent<Blueprint>();
                page.OnPointerInteraction -= OnPointerInteractionCallback;
                page.OnSelect -= OnSelectCallback;
            });
        }
        public void DisableScrollRectDragging()
        {
            isScrollRectDragDisabled = true;
        }
        public override Blueprint? GetItem(int index)
        {
            return blueprintList.getElement<Blueprint>(index);
        }
        private void OnPointerInteractionCallback(Blueprint blueprint, PointerInteractionArgs args)
        {
            var eventData = args.eventData;
            var interaction = args.interaction;
            var index = blueprintList.indexOf(blueprint);
            CallBlueprintPointerInteraction(index, args);

            if (eventData != null)
            {
                if (isScrollRectDragDisabled)
                {
                    if (interaction == PointerInteraction.EndDrag)
                    {
                        isScrollRectDragDisabled = false;
                        scrollRect.OnEndDrag(eventData);
                    }
                    else if (interaction == PointerInteraction.BeginDrag)
                    {
                        scrollRect.OnBeginDrag(eventData);
                    }
                    return;
                }

                switch (interaction)
                {
                    case PointerInteraction.BeginDrag:
                        scrollRect.OnBeginDrag(eventData);
                        return;
                    case PointerInteraction.Drag:
                        scrollRect.OnDrag(eventData);
                        return;
                    case PointerInteraction.EndDrag:
                        scrollRect.OnEndDrag(eventData);
                        return;
                }
            }
        }
        private void OnSelectCallback(Blueprint blueprint, PointerInteractionArgs args)
        {
            var index = blueprintList.indexOf(blueprint);
            CallBlueprintSelect(index, args);
        }
        [Header("Mobile")]
        [SerializeField]
        ScrollRect scrollRect = null!;
        [SerializeField]
        ElementListUI blueprintList = null!;
        private bool isScrollRectDragDisabled;
    }
}
